package com.xyz.question_bank_management_system.modules.profile.controller;
import com.xyz.question_bank_management_system.common.ApiResponse; import com.xyz.question_bank_management_system.modules.profile.entity.*; import com.xyz.question_bank_management_system.modules.profile.service.ResumeEvidenceService; import com.xyz.question_bank_management_system.util.SecurityContextUtil; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.util.*;
@RestController @RequestMapping("/api/student-profile/resumes") @PreAuthorize("hasRole('STUDENT')") @RequiredArgsConstructor public class ResumeEvidenceController {private final ResumeEvidenceService service;@PostMapping(consumes="multipart/form-data") public ApiResponse<StudentResumeDocument> upload(@RequestPart("file")MultipartFile file,@RequestParam(required=false)String consentVersion){return ApiResponse.ok(service.upload(file,consentVersion,SecurityContextUtil.getUserId()));}@GetMapping public ApiResponse<List<StudentResumeDocument>> documents(){return ApiResponse.ok(service.documents(SecurityContextUtil.getUserId()));}@GetMapping("/{resumeId}/evidence") public ApiResponse<List<StudentResumeEvidence>> evidence(@PathVariable Long resumeId){return ApiResponse.ok(service.evidence(resumeId,SecurityContextUtil.getUserId()));}@PostMapping("/{resumeId}/evidence/{evidenceId}/confirm") public ApiResponse<Void> confirm(@PathVariable Long resumeId,@PathVariable Long evidenceId,@RequestParam boolean accepted){service.confirm(resumeId,evidenceId,accepted,SecurityContextUtil.getUserId());return ApiResponse.ok();}}
